from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    rects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            minr = min(y for y, x in cells); maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells); maxc = max(x for y, x in cells)
            area = (maxr-minr+1) * (maxc-minc+1)
            # The intended figures are solid rectangles with a few cells corrupted.
            if len(cells) >= 4 and len(cells) / area >= 0.5:
                rects.append((minr, maxr, minc, maxc, color))
    out = [[bg] * w for _ in range(h)]
    for r0, r1, c0, c1, color in rects:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                out[r][c] = color
    return out
